<?php
declare(strict_types=1);require __DIR__.'/../vendor/autoload.php';use MiniErp\Repositories\{FiscalOperationRepository,StockRepository};$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$pdo=new PDO("mysql:host={$d['host']};port={$d['port']};dbname=mini_erp_tenant_14;charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$row=$pdo->query("SELECT o.id order_id,MIN(i.product_id) product_id,MIN(i.quantity) quantity FROM fiscal_orders o JOIN fiscal_order_items i ON i.order_id=o.id WHERE o.tenant_id=14 AND o.operation_type='EXIT' GROUP BY o.id HAVING COUNT(*)=1 ORDER BY o.id LIMIT 1")->fetch();if(!$row){echo"StockLotSaleGuard SKIPPED no-order\n";exit;}$pdo->beginTransaction();try{$stock=new StockRepository($pdo,14);$main=$stock->ensureMainLocation();$quantity=bcadd((string)$row['quantity'],'10',4);$lot=$stock->createLot((int)$row['product_id'],$main,'SALE-TEST-'.bin2hex(random_bytes(4)),$quantity,null,date('Y-m-d',strtotime('+1 year')),'TEST ONLY',999);$stock->setBlocked($lot,true,'TEST ONLY blocked',999);$operation=new FiscalOperationRepository($pdo,14);$method=new ReflectionMethod($operation,'allocateOrderLots');$method->setAccessible(true);try{$method->invoke($operation,(int)$row['order_id'],[['quantidade'=>$row['quantity'],'stock_lot_id'=>$lot]],'EXIT',999);throw new RuntimeException('blocked accepted');}catch(ReflectionException $e){throw$e;}catch(Throwable $e){if($e->getMessage()!=='STOCK_LOT_BLOCKED')throw$e;}$stock->setBlocked($lot,false,'',999);$method->invoke($operation,(int)$row['order_id'],[['quantidade'=>$row['quantity'],'stock_lot_id'=>$lot]],'EXIT',999);$itemLot=(int)$pdo->query('SELECT stock_lot_id FROM fiscal_order_items WHERE order_id='.(int)$row['order_id'].' ORDER BY id LIMIT 1')->fetchColumn();if($itemLot!==$lot)throw new RuntimeException('lot not linked');$balance=(float)$pdo->query('SELECT quantity_available FROM stock_lots WHERE id='.$lot)->fetchColumn();if(abs($balance-10.0)>.0001)throw new RuntimeException('balance not consumed');echo"StockLotSaleGuardIntegration OK\n";}finally{$pdo->rollBack();}
